import math


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    P = [0] * (n + 1)
    for i, x in enumerate(a):
        P[i + 1] = P[i] + x

    hull: list[int] = []
    best_p, best_q = P[k], k

    for r in range(k, n + 1):
        l = r - k
        while len(hull) >= 2:
            l1, l2 = hull[-2], hull[-1]
            if (P[l2] - P[l1]) * (l - l2) >= (P[l] - P[l2]) * (l2 - l1):
                hull.pop()
            else:
                break
        hull.append(l)

        lo, hi = 0, len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            l1, l2 = hull[mid], hull[mid + 1]
            if (P[r] - P[l1]) * (r - l2) <= (P[r] - P[l2]) * (r - l1):
                lo = mid + 1
            else:
                hi = mid

        best_l = hull[lo]
        p, q = P[r] - P[best_l], r - best_l
        if p * best_q > best_p * q:
            best_p, best_q = p, q

    g = math.gcd(best_p, best_q)
    return [best_p // g, best_q // g]
